import * as React from "react"
import { cn } from "@/lib/utils"

const RATIOS = {
  capsule: "aspect-[231/87]",
  header: "aspect-[460/215]",
  hero: "aspect-[616/353]",
  screenshot: "aspect-video",
  portrait: "aspect-[2/3]",
} as const

/**
 * Artwork slot. Renders `src` if given, otherwise a deterministic gradient
 * placeholder seeded from `title`, so layouts look right before real art exists.
 */
function CoverArt({
  src,
  title,
  ratio = "capsule",
  className,
  children,
  ...props
}: Omit<React.ComponentProps<"div">, "title"> & {
  src?: string
  title: string
  /** capsule 231:87 · header 460:215 · hero 616:353 · screenshot 16:9 · portrait 2:3 */
  ratio?: keyof typeof RATIOS
}) {
  const hue = React.useMemo(() => {
    let h = 0
    for (const ch of title) h = (h * 31 + ch.charCodeAt(0)) % 360
    return h
  }, [title])

  return (
    <div
      data-slot="cover-art"
      className={cn("relative overflow-hidden bg-surface", RATIOS[ratio], className)}
      {...props}
    >
      {src ? (
        <img src={src} alt={title} loading="lazy" className="size-full object-cover" />
      ) : (
        <div
          role="img"
          aria-label={title}
          className="flex size-full items-center justify-center p-3 text-center"
          style={{
            background: `radial-gradient(circle at 30% 20%, hsl(${hue} 70% 55% / .9), transparent 60%),
              radial-gradient(circle at 80% 90%, hsl(${(hue + 60) % 360} 70% 35%), transparent 65%),
              linear-gradient(135deg, hsl(${hue} 45% 18%), hsl(${(hue + 200) % 360} 40% 10%))`,
          }}
        >
          <span className="font-heading text-lg leading-tight font-black tracking-tight text-white/90 uppercase drop-shadow-[0_2px_4px_rgb(0_0_0/0.6)]">
            {title}
          </span>
        </div>
      )}
      {children}
    </div>
  )
}

export { CoverArt }

import { TrendingUpIcon } from "lucide-react"
import * as React from "react"
import {
  Carousel,
  CarouselContent,
  CarouselDots,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
  type CarouselApi,
} from "@/components/ui/carousel"
import { cn } from "@/lib/utils"
import { CoverArt } from "./cover-art"
import { PriceTag } from "./price-tag"
import { ReviewSummary, type ReviewRating } from "./review-summary"

export type FeaturedItem = {
  id: string
  title: string
  image?: string
  screenshots?: string[]
  rating: ReviewRating
  reviewCount: number
  /** Why it's featured: "Top Seller", "Now Available", "Recommended because…" */
  reason?: { title: string; detail?: string }
  price: number
  originalPrice?: number
  href?: string
}

export type FeaturedHeroProps = {
  items: FeaturedItem[]
  currency?: string
  /** Auto-advance interval in ms. Pauses on hover and focus. `0` disables. */
  autoPlay?: number
  /** Fires when a slide is clicked. Call `e.preventDefault()` for client-side routing. */
  onSelect?: (item: FeaturedItem, e: React.MouseEvent<HTMLAnchorElement>) => void
  /** Fires whenever the visible slide changes (arrows, dots, swipe, autoplay). */
  onSlideChange?: (index: number, item: FeaturedItem) => void
  className?: string
}

/**
 * The homepage hero: wide art (~70%) + info panel (~30%) with title, reviews,
 * a 2×2 screenshot grid, the "reason" line, and price pinned bottom-right.
 */
function FeaturedHero({ items, currency, autoPlay = 0, onSelect, onSlideChange, className }: FeaturedHeroProps) {
  const [api, setApi] = React.useState<CarouselApi>()
  const [paused, setPaused] = React.useState(false)
  const latest = React.useRef({ items, onSlideChange })
  latest.current = { items, onSlideChange }

  React.useEffect(() => {
    if (!api) return
    const handle = () => {
      const i = api.selectedScrollSnap()
      const item = latest.current.items[i]
      if (item) latest.current.onSlideChange?.(i, item)
    }
    api.on("select", handle)
    return () => {
      api.off("select", handle)
    }
  }, [api])

  React.useEffect(() => {
    if (!api || !autoPlay || paused) return
    const id = window.setInterval(() => api.scrollNext(), autoPlay)
    return () => window.clearInterval(id)
  }, [api, autoPlay, paused])

  return (
    <Carousel
      setApi={setApi}
      opts={{ loop: true }}
      className={cn("mx-auto w-full", className)}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocusCapture={() => setPaused(true)}
      onBlurCapture={() => setPaused(false)}
    >
      <CarouselContent>
        {items.map((item) => (
          <CarouselItem key={item.id}>
            <a
              href={item.href ?? "#"}
              onClick={(e) => onSelect?.(item, e)}
              className="grid shadow-[0_0_8px_rgb(0_0_0/0.5)] transition-[filter] duration-200 ease-out outline-none hover:brightness-105 focus-visible:ring-2 focus-visible:ring-ring md:grid-cols-[7fr_3fr]"
            >
              <CoverArt title={item.title} src={item.image} ratio="hero" className="md:aspect-auto md:h-full" />
              <div className="flex flex-col gap-3 bg-hero-info p-4 md:min-h-[353px]">
                <h3 className="text-xl leading-tight font-medium">{item.title}</h3>
                <ReviewSummary rating={item.rating} count={item.reviewCount} />
                <div className="grid grid-cols-2 gap-2">
                  {[0, 1, 2, 3].map((i) => (
                    <CoverArt
                      key={i}
                      ratio="screenshot"
                      title={`${item.title} ${i + 1}`}
                      src={item.screenshots?.[i]}
                      className="opacity-80 transition-opacity duration-200 hover:opacity-100 [&_span]:hidden"
                    />
                  ))}
                </div>
                <div className="mt-auto flex items-end justify-between gap-3">
                  {item.reason ? (
                    <div className="flex items-center gap-2">
                      <TrendingUpIcon className="size-8 text-sale-foreground" />
                      <div className="leading-tight">
                        <div className="text-[0.8125rem] font-medium text-sale-foreground">{item.reason.title}</div>
                        {item.reason.detail && <div className="text-[0.8125rem] text-heading">{item.reason.detail}</div>}
                      </div>
                    </div>
                  ) : (
                    <span />
                  )}
                  <PriceTag price={item.price} originalPrice={item.originalPrice} currency={currency} />
                </div>
              </div>
            </a>
          </CarouselItem>
        ))}
      </CarouselContent>
      <CarouselPrevious className="hidden xl:inline-flex" />
      <CarouselNext className="hidden xl:inline-flex" />
      <CarouselDots />
    </Carousel>
  )
}

export { FeaturedHero }

import * as React from "react"
import { cn, formatPrice } from "@/lib/utils"

const TEXT = { sm: "text-xs", default: "text-[0.8125rem]", lg: "text-base" } as const
const PCT = { sm: "px-1", default: "px-1.5", lg: "px-2.5 text-[1.375rem]" } as const
const BODY = { sm: "px-1.5 py-1", default: "px-2 py-1.5", lg: "px-3 py-2" } as const

/**
 * Price block. With a discount: [-46%][~~old~~ new], lime on olive.
 * Without: plain price on a dark chip. `price === 0` renders "Free to Play".
 */
function PriceTag({
  price,
  originalPrice,
  currency = "USD",
  locale,
  size = "default",
  className,
  ...props
}: React.ComponentProps<"div"> & {
  price: number
  originalPrice?: number
  currency?: string
  locale?: string
  size?: keyof typeof TEXT
}) {
  const discounted = originalPrice != null && originalPrice > price
  const pct = discounted ? Math.round((1 - price / originalPrice) * 100) : 0
  const fmt = (v: number) => formatPrice(v, currency, locale)

  return (
    <div
      data-slot="price-tag"
      className={cn(
        "inline-flex items-stretch overflow-hidden leading-none whitespace-nowrap",
        TEXT[size],
        className
      )}
      {...props}
    >
      {discounted && (
        <span className={cn("flex items-center bg-sale font-semibold text-sale-foreground", PCT[size])}>
          -{pct}%
        </span>
      )}
      <span
        className={cn(
          "flex items-center gap-1.5",
          BODY[size],
          discounted ? "bg-price-surface" : "bg-black/30"
        )}
      >
        {discounted && (
          <s className="text-[0.75em] text-strike decoration-strike">{fmt(originalPrice)}</s>
        )}
        <span className={cn("font-medium", discounted ? "text-sale-foreground" : "text-heading")}>
          {price === 0 ? "Free to Play" : fmt(price)}
        </span>
      </span>
    </div>
  )
}

export { PriceTag }

import { HeartIcon, ShoppingCartIcon } from "lucide-react"
import * as React from "react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { CoverArt } from "./cover-art"
import { PriceTag } from "./price-tag"

export type ProductCapsuleProps = Omit<React.ComponentProps<"div">, "title" | "onSelect"> & {
  title: string
  image?: string
  price: number
  originalPrice?: number
  currency?: string
  /** Overlay label top-left, e.g. "Today's Deal" */
  label?: string
  live?: boolean
  ratio?: "capsule" | "header" | "portrait"
  href?: string
  /** Fires when the tile is activated (click / Enter). Call `e.preventDefault()` for client-side routing. */
  onSelect?: (e: React.MouseEvent<HTMLAnchorElement>) => void
  /** Shows a cart quick-action on hover/focus. */
  onAddToCart?: () => void
  /** Shows a wishlist toggle on hover/focus. */
  onWishlistChange?: (wishlisted: boolean) => void
  /** Controlled wishlist state. */
  wishlisted?: boolean
}

/**
 * The grid tile: art on top, price anchored bottom-right.
 * Hover = slight brighten + primary glow. Never scale up.
 */
function ProductCapsule({
  title,
  image,
  price,
  originalPrice,
  currency,
  label,
  live,
  ratio = "header",
  href = "#",
  onSelect,
  onAddToCart,
  onWishlistChange,
  wishlisted = false,
  className,
  ...props
}: ProductCapsuleProps) {
  const hasActions = onAddToCart || onWishlistChange

  return (
    <div
      data-slot="product-capsule"
      className={cn(
        "group/capsule relative animate-capsule-in transition-[filter,box-shadow] duration-200 ease-out",
        "hover:shadow-glow hover:brightness-110 has-focus-visible:shadow-glow",
        className
      )}
      {...props}
    >
      <a href={href} onClick={onSelect} className="block outline-none focus-visible:ring-2 focus-visible:ring-ring">
        <CoverArt title={title} src={image} ratio={ratio}>
          {label && (
            <Badge variant="label" className="absolute top-2 left-0">
              {label}
            </Badge>
          )}
          {live && (
            <Badge variant="live" className="absolute top-2 left-2">
              Live
            </Badge>
          )}
        </CoverArt>
        <div className="flex justify-end bg-black/20">
          <PriceTag price={price} originalPrice={originalPrice} currency={currency} />
        </div>
      </a>

      {hasActions && (
        <div className="absolute top-2 right-2 flex gap-1 opacity-0 transition-opacity duration-200 ease-out group-hover/capsule:opacity-100 group-has-focus-visible/capsule:opacity-100">
          {onWishlistChange && (
            <Button
              size="icon-sm"
              variant="secondary"
              aria-label={wishlisted ? `Remove ${title} from wishlist` : `Add ${title} to wishlist`}
              aria-pressed={wishlisted}
              onClick={() => onWishlistChange(!wishlisted)}
              className="bg-black/60 backdrop-blur-sm"
            >
              <HeartIcon className={cn(wishlisted && "fill-current")} />
            </Button>
          )}
          {onAddToCart && (
            <Button size="icon-sm" variant="success" aria-label={`Add ${title} to cart`} onClick={onAddToCart}>
              <ShoppingCartIcon />
            </Button>
          )}
        </div>
      )}
    </div>
  )
}

export { ProductCapsule }

